contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);
        uint256 valBefore = c.value(); if (__ESBMC_reverted()) return;
        uint256 remBefore = c.totalRemaining(); if (__ESBMC_reverted()) return;
        bool blackBefore = c.blacklist(address(this)); if (__ESBMC_reverted()) return;
        uint256 balCBefore = address(c).balance;
        c.getTokens(); if (__ESBMC_reverted()) return;
        uint256 valAfter = c.value(); if (__ESBMC_reverted()) return;
        assert(
            !blackBefore &&
            c.balanceOf(address(this)) == valBefore &&
            c.blacklist(address(this)) &&
            c.totalRemaining() + valBefore == remBefore &&
            valAfter < valBefore
        );
    }
    receive() external payable {}
}

